    "overview": {
      "basic_info": {
        "name": "殞地紀元",
        "timeline": "2030年",
        "context": "实验性基因疗法病毒‘复兴’泄露，引发全球丧尸危机，纽克雷斯特市成重灾区"
      },
      "structure": {
        "geography": "纽克雷斯特市，美国东海岸虚构超1500万人口的科技中心，城市沦陷，郊区部分维持秩序",
        "government": "政府瘫痪，幸存者自组防御团体",
        "technology": {
          "level": "电力、通信断续，互联网信号不稳",
          "applications": {
            "medical": "病毒源自基因疗法实验",
            "surveillance": "部分监控系统仍运行",
            "transport": "地铁、港口瘫痪"
          }
        },
        "society": {
          "culture": "生存至上，信任危机普遍",
          "laws": "法律崩溃，幸存者自定规则",
          "public_perception": "对政府与科技失去信任"
        }
      },
      "core_conflict": {
        "surface": "幸存者在纽克雷斯特市求生，寻找物资与安全",
        "true_purpose": {
          "traits": [
            "病毒泄露或为实验室与跨国组织阴谋",
            "纽克雷斯特市高感染率与特殊感染者疑因独特病毒株",
            "病毒可能涉及人口控制或生物武器",
            "特殊感染者暗示病毒进化"
          ]
        }
      },
      "mechanisms": {
        "implementation": {
          "methods": [
            "病毒通过空气、体液传播，24-48小时变异",
            "高密度环境加速扩散，地铁、住宅区成感染点",
            "幸存者利用高楼分散尸群，建临时防御",
            "少数人搜集实验室资料寻解药"
          ],
          "tools": [
            "武器：简易武器与枪械",
            "防御：高楼、地下商场",
            "通信：断续无线电与手机"
          ]
        },
        "public_facade": [
          "初期政府称病毒可控，呼吁待援",
          "媒体失联，谣言加剧混乱"
        ],
        "hidden_operations": [
          "实验室或秘密研究病毒变异",
          "特殊感染者行为疑为实验副产物"
        ]
      },
      "background": {
        "history": {
          "origin": "2029年末，‘复兴’病毒全球泄露",
          "development": "2030年初，纽克雷斯特市因人口密度迅速沦陷",
          "current_state": "城市中心失守，尸群扩大"
        },
        "politics": {
          "ruling_power": "政府瓦解，幸存者各自为政",
          "opposition": "少数人探寻病毒真相",
          "public_policy": "以生存与防御为主"
        },
        "social_impact": {
          "survivor_dynamics": "物资争夺与信任危机，少数合作",
          "zombie_role": "威胁与病毒秘密载体",
          "resistance": "部分幸存者反抗尸群与阴谋"
        }
      },
      "zombies": {
        "types": [
          {
            "name": "新感染者",
            "traits": "行动迅速，攻击性强，24-48小时完全变异"
          },
          {
            "name": "早期变异者",
            "traits": "感染超一周，身体腐烂，速度慢，力量增强"
          },
          {
            "name": "特殊感染者",
            "traits": "罕见，具夜视或短暂记忆，纽克雷斯特市频率较高"
          }
        ],
        "behavior": [
          "受本能驱使，攻击活物，追逐声音与快速目标",
          "无组织，噪音引小型尸群，纽克雷斯特市尸群庞大",
          "徘徊熟悉地点，如购物中心、地铁站"
        ],
        "weaknesses": [
          "头部重创致命，身体伤害仅减缓",
          "对强光、高温敏感，低温行动迟缓",
          "感知广但易被分散，高楼环境可利用"
        ]
      }
    }
  }
}

