entries.content:
{
  "Special_Infected": {
    "context": "在纽克雷斯特市，‘复兴’病毒导致部分感染者变异为特殊感染者，表现出超常能力，威胁幸存者生存。以下为主要类型，融合《求生之路》与《生化危机》元素。",
    "types": [
      {
        "name": "猎人 (Hunter)",
        "traits": "敏捷异常，能高空跳跃扑倒幸存者，爪击造成持续伤害。",
        "behavior": "潜伏于高处或阴影，锁定落单目标，发出低吼后突袭。",
        "weaknesses": "近战武器可打断扑击，火力集中可快速击杀。"
      },
      {
        "name": "烟鬼 (Smoker)",
        "traits": "舌头可远距离缠绕并拖拽幸存者，释放烟雾干扰视野。",
        "behavior": "藏于远处，利用舌头偷袭，拖拽目标至尸群或险地。",
        "weaknesses": "舌头被近战攻击可断裂，烟雾中移动缓慢，易被围攻。"
      },
      {
        "name": "胖子 (Boomer)",
        "traits": "肥胖，呕吐物吸引尸群，死亡时爆炸，喷溅胆汁。",
        "behavior": "靠近幸存者后呕吐，引来尸群，主动接近以自爆。",
        "weaknesses": "行动迟缓，远程击杀可避免爆炸，胆汁效果短时间内可清理。"
      },
      {
        "name": "坦克 (Tank)",
        "traits": "体型巨大，力量惊人，投掷巨石，冲撞造成范围伤害。",
        "behavior": "正面冲锋，破坏障碍物，优先攻击密集人群。",
        "weaknesses": "速度慢，需持续火力压制，引至狭窄地形可限制移动。"
      },
      {
        "name": "女巫 (Witch)",
        "traits": "静止时哭泣，受到惊扰后以极高速度和伤害追杀单一目标。",
        "behavior": "潜伏于黑暗角落，安静时无害，被灯光或声音激怒后狂暴。",
        "weaknesses": "避免惊扰为最佳策略，若触发需集中火力速杀，头部最脆弱。"
      },
      {
        "name": "骑师 (Jockey)",
        "traits": "身材矮小，跳跃到幸存者背上控制其移动，造成持续伤害。",
        "behavior": "快速接近，骑在目标背上驱使其远离团队或进入险境。",
        "weaknesses": "近战攻击可将其击落，火力集中可迅速消灭。"
      },
      {
        "name": "冲锋者 (Charger)",
        "traits": "体型壮硕，冲撞并抓住单一目标，撞击墙面或障碍造成额外伤害。",
        "behavior": "直线冲锋，抓住目标后连续猛击，直至目标死亡或被打断。",
        "weaknesses": "冲锋路径可预测，侧身闪避或集中火力可阻止其行动。"
      },
      {
        "name": "喷吐者 (Spitter)",
        "traits": "喷射腐蚀性酸液，地面形成持续伤害的酸池。",
        "behavior": "保持距离，喷吐酸液后迅速逃离，优先攻击密集人群。",
        "weaknesses": "移动缓慢，远程武器可快速击杀，避开酸池可减少威胁。"
      },
      {
        "name": "猎杀者 (Hunter - Resident Evil)",
        "traits": "爬行类人形生物，强壮四肢，锋利爪子可撕裂目标，耐力极高。",
        "behavior": "高速爬行于墙面或地面，突袭并用爪击重创目标，偏好近战。",
        "weaknesses": "头部为弱点，爆炸物或重武器可有效击杀，需防其快速移动。"
      },
      {
        "name": "舔食者 (Licker)",
        "traits": "无眼爬行怪物，长舌可远距离穿刺或缠绕，感知声音与震动。",
        "behavior": "潜伏于天花板或暗处，利用长舌偷袭，优先攻击孤立目标。",
        "weaknesses": "对强光敏感，头部或舌根重创可致命，需防其隐蔽性。"
      },
      {
        "name": "吸脑者 (Brain Sucker)",
        "traits": "头部畸形，触手可钻入目标头部吸取脑组织，移动缓慢但攻击致命。",
        "behavior": "缓慢靠近，锁定目标后用触手攻击，偏好静止或受伤的幸存者。",
        "weaknesses": "行动迟缓，远程武器可轻松击杀，需避免近距离接触。"
      }
    ],
    "notes": {
      "frequency": "纽克雷斯特市特殊感染者出现频率高于其他地区，可能与本地实验室的病毒株有关。",
      "environment_impact": "高楼与地铁系统为特殊感染者提供理想伏击点，幸存者需谨慎利用地形。",
      "survivor_strategies": "团队协作至关重要，分散注意力、利用地形和火力压制可有效应对。"
    }
  }
}

